export LANG=C LC_ALL=C
D=/opt/lzh/v7re/work/hclk48
rm -rf $D; mkdir -p $D; cd $D || exit 1
base64 -d > /tmp/h48.tgz <<'B64EOF'

B64EOF
tar xzf /tmp/h48.tgz
for t in m0 m1 m2 m3 m4 m5 m6 p0 p1 p2 p3 p4 p5; do
  echo "run $t"
done | xargs -P 13 -I{} sh -c '/opt/lzh/Xilinx/Vivado/2017.2/bin/vivado -mode batch -notrace -source {}.tcl > {}.log 2>&1; grep -q DONE_{} {}.log && echo "OK {} $(grep CHK_SITE {}.log)" || { echo "FAIL {}"; tail -5 {}.log; }'
tar czf /tmp/hclk48_out.tgz *.bit *.pips
echo HCLK48DONE
